-- 办公平台基础表
CREATE TABLE IF NOT EXISTS office_platform_app (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id VARCHAR(64) NOT NULL, platform VARCHAR(32) NOT NULL, app_id VARCHAR(128) NOT NULL, secret_reference VARCHAR(255) NOT NULL, redirect_uri VARCHAR(512), signing_secret_reference VARCHAR(255), capabilities TEXT, enabled TINYINT NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 0, deleted TINYINT NOT NULL DEFAULT 0, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uk_office_app_tenant_platform (tenant_id, platform));
CREATE TABLE IF NOT EXISTS office_identity_binding (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id VARCHAR(64) NOT NULL, user_id BIGINT NOT NULL, platform VARCHAR(32) NOT NULL, external_user_id VARCHAR(255) NOT NULL, status VARCHAR(32) NOT NULL, enabled TINYINT NOT NULL DEFAULT 1, version INT NOT NULL DEFAULT 0, deleted TINYINT NOT NULL DEFAULT 0, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uk_office_binding_external (tenant_id, platform, external_user_id), UNIQUE KEY uk_office_binding_user (tenant_id, platform, user_id));
CREATE TABLE IF NOT EXISTS office_organization_mapping (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id VARCHAR(64) NOT NULL, platform VARCHAR(32) NOT NULL, external_org_id VARCHAR(255) NOT NULL, external_user_id VARCHAR(255), apex_dept_id VARCHAR(64), apex_user_id VARCHAR(64), version INT NOT NULL DEFAULT 0, deleted TINYINT NOT NULL DEFAULT 0, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uk_office_org (tenant_id, platform, external_org_id));
CREATE TABLE IF NOT EXISTS office_sync_task (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id VARCHAR(64) NOT NULL, platform VARCHAR(32) NOT NULL, cursor_value VARCHAR(512), state VARCHAR(32) NOT NULL, failure_message VARCHAR(1000), version INT NOT NULL DEFAULT 0, deleted TINYINT NOT NULL DEFAULT 0, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uk_office_sync (tenant_id, platform));
